package cn.blockforge.generated.generatedmod.formation.carving;
import cn.blockforge.generated.generatedmod.WuXingItems;import cn.blockforge.generated.generatedmod.WuXingBlocks;import cn.blockforge.generated.generatedmod.items.CultivationLogic;
import cn.blockforge.generated.generatedmod.fixtures.GameTestPlayer;import net.minecraft.gametest.framework.*;import net.minecraft.core.BlockPos;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.nbt.CompoundTag;
import net.minecraftforge.gametest.*;
@GameTestHolder("wuxingxiantu_carving") @PrefixGameTestTemplate(false)
public final class CarvingGameTests {
 private static CarvingEye eye(GameTestHelper h){h.setBlock(new BlockPos(2,1,2),CarvingRegistry.EYE.get());return (CarvingEye)h.getLevel().getBlockEntity(h.absolutePos(new BlockPos(2,1,2)));}
 @GameTest(template="empty") public static void registeredCoreHasFormationTabAndRealMenu(GameTestHelper h){h.assertTrue(cn.blockforge.generated.generatedmod.registry.ModTabs.category(new ItemStack(CarvingRegistry.CORE_ITEM.get()))==cn.blockforge.generated.generatedmod.registry.ModTabs.Category.FORMATIONS,"Core missing formation tab");h.assertTrue(CarvingRegistry.MENU.get()!=null&&CarvingRegistry.TILE.get().isValid(CarvingRegistry.EYE.get().defaultBlockState()),"Missing menu or block entity");h.succeed();}
 @GameTest(template="empty") public static void coreConvertsOnceAtFixedPosition(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,1,2));h.setBlock(new BlockPos(2,1,2),CarvingRegistry.CORE.get());var be=(CarvingEye)h.getLevel().getBlockEntity(pos);try(var p=new GameTestPlayer(h.getLevel())){p.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()+.5);be.select(2);h.assertTrue(be.carve(p),"Real core conversion failed");var next=(CarvingEye)h.getLevel().getBlockEntity(pos);h.assertTrue(next.isEye()&&next.kind()==2&&!next.carve(p),"Wrong formation type or duplicate conversion");h.assertTrue(!next.powered(),"An unfueled eye is active");}h.succeed();}
 @GameTest(template="empty") public static void farPlayerCannotCarveOrForgeMenuActions(GameTestHelper h){var pos=h.absolutePos(new BlockPos(2,1,2));h.setBlock(new BlockPos(2,1,2),CarvingRegistry.CORE.get());var be=(CarvingEye)h.getLevel().getBlockEntity(pos);try(var p=new GameTestPlayer(h.getLevel())){p.setPos(pos.getX()+100,pos.getY(),pos.getZ());var menu=new CarvingMenu(7,p.getInventory(),be);h.assertTrue(!menu.clickMenuButton(p,10)&&!be.carve(p)&&!be.isEye(),"Remote conversion bypass");}h.succeed();}
 @GameTest(template="empty") public static void fixedPointFuelIsExactAndAtomic(GameTestHelper h){var be=eye(h);var held=new ItemStack(WuXingItems.SPIRIT_STONE.get(),2);h.assertTrue(be.insertStone(held,false)==2&&held.isEmpty(),"Stone deposit mismatch");for(int i=0;i<1200;i++)h.assertTrue(be.spendTick(1,1),"Fuel ended early");h.assertTrue(be.charge()==0&&be.fuel.getItem(0).getCount()==1,"One minute did not use exactly one low stone");h.assertTrue(!be.spendTick(1201,1)&&be.fuel.getItem(0).getCount()==1,"Insufficient budget partially consumed stones");h.assertTrue(be.spendTick(1200,1)&&be.fuel.isEmpty(),"Exact final charge failed");h.assertTrue(!be.spendTick(1,1),"Exhausted fuel generated power");h.succeed();}
 @GameTest(template="empty") public static void unconfiguredOrDisallowedFuelNeverBurns(GameTestHelper h){var be=eye(h);be.insertStone(new ItemStack(WuXingItems.SPIRIT_STONE_MIDDLE.get(),1),false);h.assertTrue(!be.spendTick(0,15)&&!be.spendTick(1,0)&&!be.spendTick(1,1),"Unconfigured or disallowed operation");h.assertTrue(be.fuel.getItem(0).getCount()==1,"Disallowed stone consumed");h.assertTrue(be.spendTick(1,2)&&be.charge()==10799,"Middle stone value differs from unified currency");h.assertTrue(!be.spendTick(1,1)&&be.charge()==10799,"Reserved disallowed fuel was spent");h.succeed();}
 @GameTest(template="empty") public static void saveReloadPreservesStonesAndPrepaidValue(GameTestHelper h){var be=eye(h);be.insertStone(new ItemStack(WuXingItems.SPIRIT_STONE_EXQUISITE.get(),3),false);be.spendTick(7,8);var tag=be.saveWithoutMetadata();var other=new CarvingEye(be.getBlockPos(),be.getBlockState());other.load(tag);h.assertTrue(other.charge()==874793&&other.fuel.getItem(0).getCount()==2&&other.reserveGrade()==3,"NBT reload lost paid energy or stored stones");var invalid=new CompoundTag();invalid.putLong("FormationCharge",Long.MAX_VALUE);invalid.putInt("FormationKind",999);other.load(invalid);h.assertTrue(other.charge()<=874800&&other.kind()==2,"Unbounded saved state");h.succeed();}
 @GameTest(template="empty") public static void realTickerStopsAndDoesNotDuplicateTickCharge(GameTestHelper h){var be=eye(h);int old=CarvingConfig.GATHER_COST.get(),mask=CarvingConfig.GRADES.get();try{CarvingConfig.GATHER_COST.set(1);CarvingConfig.GRADES.set(1);be.insertStone(new ItemStack(WuXingItems.SPIRIT_STONE.get()),false);CarvingEye.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(be.powered()&&be.charge()==1199,"Real ticker failed");CarvingEye.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(be.charge()==1199,"Repeated same-tick update charged twice");be.toggle();h.assertTrue(!be.powered(),"Manual pause did not stop field");}finally{CarvingConfig.GATHER_COST.set(old);CarvingConfig.GRADES.set(mask);}h.succeed();}
 @GameTest(template="empty") public static void gatheringUsesExistingBuffWithoutStackingAccount(GameTestHelper h){var be=eye(h);int old=CarvingConfig.GATHER_COST.get(),mask=CarvingConfig.GRADES.get();try(var p=new GameTestPlayer(h.getLevel())){p.setPos(be.getBlockPos().getX()+1.5,be.getBlockPos().getY()+.2,be.getBlockPos().getZ()+.5);h.assertTrue(!CultivationLogic.onArray(p),"Unpowered eye granted boost");CarvingConfig.GATHER_COST.set(1);CarvingConfig.GRADES.set(1);be.insertStone(new ItemStack(WuXingItems.SPIRIT_STONE.get()),false);CarvingEye.tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(CultivationLogic.onArray(p),"Powered gathering eye did not use existing boost path");}finally{CarvingConfig.GATHER_COST.set(old);CarvingConfig.GRADES.set(mask);}h.succeed();}
 @GameTest(template="empty") public static void dismantlePreservesReserveAndDropsOnlyUnspentStones(GameTestHelper h){var be=eye(h);be.insertStone(new ItemStack(WuXingItems.SPIRIT_STONE_EXQUISITE.get(),3),false);be.spendTick(7,8);var drops=net.minecraft.world.level.block.Block.getDrops(be.getBlockState(),h.getLevel(),be.getBlockPos(),be);h.assertTrue(drops.size()==1&&drops.get(0).is(CarvingRegistry.CORE_ITEM.get()),"Eye did not return exactly one core");var tag=drops.get(0).getTagElement("BlockEntityTag");h.assertTrue(tag!=null&&tag.getLong("FormationCharge")==874793&&tag.getInt("ReserveGrade")==3,"Prepaid value missing from returned core");var pos=be.getBlockPos();h.getLevel().destroyBlock(pos,false);var items=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(2));int count=items.stream().filter(e->e.getItem().is(WuXingItems.SPIRIT_STONE_EXQUISITE.get())).mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(count==2,"Unspent stones were lost or duplicated on removal");h.succeed();}
 @GameTest(template="empty") public static void fullFuelSlotsRejectWithoutShrinkingHeldStack(GameTestHelper h){var be=eye(h);for(int i=0;i<4;i++)be.fuel.setItem(i,new ItemStack(WuXingItems.SPIRIT_STONE.get(),64));var held=new ItemStack(WuXingItems.SPIRIT_STONE.get(),17);h.assertTrue(be.insertStone(held,false)==0&&held.getCount()==17,"Full storage swallowed stones");h.assertTrue(be.insertStone(new ItemStack(Items.DIAMOND,3),false)==0,"Non-stone accepted");h.succeed();}
 @GameTest(template="empty") public static void placingTheRealCoreItemOpensSelectionMenu(GameTestHelper h){var ground=h.absolutePos(new BlockPos(2,1,2));h.setBlock(new BlockPos(2,1,2),Blocks.STONE);try(var p=new GameTestPlayer(h.getLevel())){p.setPos(ground.getX()+2.5,ground.getY()+1,ground.getZ()+.5);p.getInventory().setItem(0,new ItemStack(CarvingRegistry.CORE_ITEM.get()));var context=new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(ground).add(0,.5,0),net.minecraft.core.Direction.UP,ground,false));h.assertTrue(p.getMainHandItem().getItem().useOn(context).consumesAction(),"Core placement failed");h.assertTrue(h.getLevel().getBlockState(ground.above()).is(CarvingRegistry.CORE.get())&&p.containerMenu instanceof CarvingMenu,"Placing core did not open the selection UI");}h.succeed();}
 private CarvingGameTests(){}
}
